<template><section class="g-advanced-filter"><div v-for="(c,i) in modelValue" :key="i" class="condition"><el-select v-model="c.field" placeholder="字段"><el-option v-for="f in fields" :key="f.value" :label="f.label" :value="f.value"/></el-select><el-select v-model="c.operator"><el-option label="等于" value="eq"/><el-option label="包含" value="contains"/><el-option label="不等于" value="neq"/></el-select><el-input v-model="c.value"/><el-button link type="danger" @click="remove(i)">删除</el-button></div><el-button @click="add">＋ 添加条件</el-button><el-button type="primary" @click="$emit('apply',modelValue)">应用筛选</el-button></section></template><script setup lang="ts">export interface FilterCondition{field:string;operator:string;value:string}const p=defineProps<{modelValue:FilterCondition[];fields:{label:string;value:string}[]}>();const emit=defineEmits<{(e:'update:modelValue',v:FilterCondition[]):void;(e:'apply',v:FilterCondition[]):void}>();const add=()=>emit('update:modelValue',[...p.modelValue,{field:'',operator:'eq',value:''}]);const remove=(i:number)=>emit('update:modelValue',p.modelValue.filter((_,n)=>n!==i));</script><style scoped src="./style.scss"></style>
